let lastScrollTop=0,header=document.querySelector("header:has(.darkify_header)");window.addEventListener("scroll",function(){var e=window.pageYOffset||document.documentElement.scrollTop;200<e?header.classList.add("is-sticky"):header.classList.remove("is-sticky"),e>lastScrollTop&&50<e?(header.classList.add("scroll-down"),header.classList.remove("scroll-up")):(header.classList.add("scroll-up"),header.classList.remove("scroll-down")),lastScrollTop=e<=0?0:e});